import React, { useState, useMemo, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const COLS = [
  { key: "id", label: "ID" },
  { key: "first_name", label: "First Name" },
  { key: "last_name", label: "Last Name" },
  { key: "email", label: "Email" },
  { key: "status", label: "Status" },
  { key: "role", label: "Role" }
];

const STATUS_COLOR = { Active: "#22c55e", Pending: "#94a3b8", Inactive: "#f87171" };

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [sortKey, setSortKey] = useState("last_name");
  const [sortDir, setSortDir] = useState("asc");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [gotoVal, setGotoVal] = useState("");

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];
  const search = ((model && model.search) || "").trim().toLowerCase();
  const activeOnly = !!(model && model.activeOnly);
  const roles = (model && Array.isArray(model.roles)) ? model.roles : [];
  const roleKey = roles.join("|");

  const rows = useMemo(() => {
    let list = data.filter(function (r) {
      if (activeOnly && String(r.status) !== "Active") return false;
      if (roles.length && roles.indexOf(String(r.role == null ? "" : r.role)) < 0) return false;
      if (search) {
        const hay = (String(r.id) + " " + String(r.first_name == null ? "" : r.first_name) + " " + String(r.last_name == null ? "" : r.last_name) + " " + String(r.email == null ? "" : r.email) + " " + String(r.status == null ? "" : r.status) + " " + String(r.role == null ? "" : r.role)).toLowerCase();
        if (hay.indexOf(search) < 0) return false;
      }
      return true;
    });
    list.sort(function (a, b) {
      if (sortKey === "id") { const av = Number(a.id), bv = Number(b.id); return sortDir === "asc" ? av - bv : bv - av; }
      const av = (a[sortKey] == null ? "" : String(a[sortKey]));
      const bv = (b[sortKey] == null ? "" : String(b[sortKey]));
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    return list;
  }, [data, search, activeOnly, roleKey, sortKey, sortDir]);

  useEffect(() => { setPage(1); }, [search, activeOnly, roleKey, data.length]);

  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const start = (safePage - 1) * pageSize;
  const pageRows = rows.slice(start, start + pageSize);

  const onSort = (k) => {
    if (k === sortKey) setSortDir(sortDir === "asc" ? "desc" : "asc");
    else { setSortKey(k); setSortDir("asc"); }
  };
  const goToPage = (p) => {
    if (!Number.isFinite(p)) return;
    setPage(Math.max(1, Math.min(totalPages, Math.floor(p))));
  };
  const onGotoSubmit = (e) => {
    if (e.key === "Enter") { const n = parseInt(gotoVal, 10); if (!isNaN(n)) goToPage(n); setGotoVal(""); }
  };
  const openRow = (row) => {
    appsmith.updateModel({ selectedUserId: row.id });
  };

  if (model.isLoading) {
    return React.createElement("div", { className: "skel" }, "Loading users...");
  }

  const arrows = (k) => React.createElement("span", { className: "sort" },
    React.createElement("span", { className: (sortKey === k && sortDir === "asc") ? "active" : "" }, "\u25b2"),
    React.createElement("span", { className: (sortKey === k && sortDir === "desc") ? "active" : "" }, "\u25bc")
  );

  const statusCell = (s) => React.createElement("span", { className: "status" },
    React.createElement("span", { className: "dot", style: { background: STATUS_COLOR[s] || "#94a3b8" } }),
    (s == null ? "" : s)
  );

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "meta" }, rows.length + " Records"),
    React.createElement("table", { className: "tbl" },
      React.createElement("thead", null,
        React.createElement("tr", null,
          COLS.map((c) => React.createElement("th", { key: c.key, onClick: () => onSort(c.key) }, c.label, arrows(c.key)))
        )
      ),
      React.createElement("tbody", null,
        pageRows.length === 0
          ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: COLS.length }, "No users found"))
          : pageRows.map((r, i) => React.createElement("tr", { key: (r.id != null ? r.id : i), onClick: () => openRow(r) },
              React.createElement("td", null, React.createElement("span", { className: "idlink" }, r.id)),
              React.createElement("td", null, (r.first_name == null ? "" : r.first_name)),
              React.createElement("td", null, (r.last_name == null ? "" : r.last_name)),
              React.createElement("td", null, (r.email == null ? "" : r.email)),
              React.createElement("td", null, statusCell(r.status)),
              React.createElement("td", null, (r.role == null ? "" : r.role))
            ))
      )
    ),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => goToPage(safePage - 1) }, "\u2039"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("span", { className: "gotolbl" }, "of " + totalPages),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => goToPage(safePage + 1) }, "\u203a"),
      React.createElement("span", { className: "gotolbl" }, "Go to"),
      React.createElement("input", { className: "goto", type: "number", min: 1, max: totalPages, value: gotoVal, onChange: (e) => setGotoVal(e.target.value), onKeyDown: onGotoSubmit, placeholder: String(safePage) }),
      React.createElement("select", { className: "psize", value: pageSize, onChange: (e) => { setPageSize(Number(e.target.value)); setPage(1); } }, [10, 20, 30, 40, 50, 100].map(function(n){ return React.createElement("option", { key: n, value: n }, n + "/page"); }))
    )
  );
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

